240.   private continueGame(): void {
241.     if (this.sceneTransitions.isPending) return;
242.     const save = loadGame();
243.     if (!save) return;
244.     const defeatedBosses = new Set(save.defeatedBosses);
245.     const weatherState = save.weatherState ?? createWeatherState();
246.     const timeStep = save.timeStep ?? 0;
247.     const pendingCutsceneId = getNextPendingCutscene(save.player.progression);
248.     saveGame(
249.       save.player,
250.       defeatedBosses,
251.       save.codex,
252.       save.player.appearanceId,
253.       timeStep,
254.       weatherState,
255.     );
256.     this.sceneTransitions.startWithFade(() => {
257.       const state = {
258.         player: save.player,
259.         defeatedBosses,
260.         codex: save.codex,
261.         timeStep,
262.         weatherState,
263.         savedSpecialNpcs: [],
264.       };
265.       if (pendingCutsceneId === CAMPAIGN_EPILOGUE_CUTSCENE_ID) {
266.         this.scene.start("EndingScene", {
267.           ...state,
268.           cutsceneId: pendingCutsceneId,
269.           replay: false,
270.         });
271.       } else if (pendingCutsceneId) {
272.         this.scene.start("CutsceneScene", {
273.           ...state,
274.           cutsceneId: pendingCutsceneId,
275.           replay: false,
276.         });
277.       } else {
278.         this.scene.start("OverworldScene", state);
279.       }
280.     }, {
281.       duration: 500,
282.       label: "continue game",
283.     });
284.   }
