22. function parseUrl(value: string): URL | null {
23.   try {
24.     return new URL(value);
25.   } catch {
26.     return null;
27.   }
28. }
29. 
30. function hasSafeCredentials(url: URL): boolean {
31.   return url.username.length === 0 && url.password.length === 0;
32. }
33. 
34. export function isAllowedExternalUrl(value: string): boolean {
35.   const url = parseUrl(value);
36.   if (!url || url.protocol !== "https:" || !hasSafeCredentials(url)) {
37.     return false;
38.   }
39.   return ALLOWED_EXTERNAL_DESTINATIONS.some(
40.     ({ origin, pathPrefix }) => url.origin === origin
41.       && (
42.         url.pathname === pathPrefix
43.         || url.pathname.startsWith(`${pathPrefix}/`)
44.       ),
45.   );
46. }
47. 
48. export function isAllowedDevelopmentUrl(value: string): boolean {
49.   const url = parseUrl(value);
50.   if (!url || url.protocol !== "http:" || !hasSafeCredentials(url)) {
51.     return false;
52.   }
53.   if (url.hostname !== "127.0.0.1" && url.hostname !== "localhost") {
54.     return false;
55.   }
56.   const port = Number.parseInt(url.port, 10);
57.   return Number.isInteger(port) && port >= 1 && port <= 65_535;
58. }
