60. export function isAllowedRendererNavigation(
61.   value: string,
62.   rendererUrl: string,
63. ): boolean {
64.   const target = parseUrl(value);
65.   const renderer = parseUrl(rendererUrl);
66.   if (!target || !renderer || !hasSafeCredentials(target)) return false;
67.   return target.protocol === renderer.protocol
68.     && target.hostname === renderer.hostname
69.     && target.port === renderer.port;
70. }
71. 
72. export function isAllowedRendererResource(
73.   value: string,
74.   developmentUrl?: string,
75. ): boolean {
76.   const target = parseUrl(value);
77.   if (!target || !hasSafeCredentials(target)) return false;
78.   if (target.protocol === `${DESKTOP_APP_SCHEME}:`) {
79.     return target.hostname === DESKTOP_APP_HOST;
80.   }
81.   if (!developmentUrl || !isAllowedDevelopmentUrl(developmentUrl)) {
82.     return false;
83.   }
84.   const development = new URL(developmentUrl);
85.   const allowedProtocols = development.protocol === "https:"
86.     ? ["https:", "wss:"]
87.     : ["http:", "ws:"];
88.   return allowedProtocols.includes(target.protocol)
89.     && target.hostname === development.hostname
90.     && target.port === development.port;
91. }
