93. export function resolveAppAssetPath(
94.   requestUrl: string,
95.   rendererRoot: string,
96. ): string | null {
97.   const url = parseUrl(requestUrl);
98.   if (
99.     !url
100.     || url.protocol !== `${DESKTOP_APP_SCHEME}:`
101.     || url.hostname !== DESKTOP_APP_HOST
102.     || !hasSafeCredentials(url)
103.   ) {
104.     return null;
105.   }
106. 
107.   let decodedPath: string;
108.   try {
109.     decodedPath = decodeURIComponent(url.pathname);
110.   } catch {
111.     return null;
112.   }
113.   if (decodedPath.includes("\0")) return null;
114. 
115.   const relativePath = decodedPath === "/"
116.     ? "index.html"
117.     : decodedPath.replace(/^\/+/, "");
118.   const root = resolve(rendererRoot);
119.   const candidate = resolve(root, relativePath);
120.   const fromRoot = relative(root, candidate);
121.   if (
122.     fromRoot.length === 0
123.     || fromRoot.startsWith("..")
124.     || isAbsolute(fromRoot)
125.   ) {
126.     return null;
127.   }
128.   return candidate;
129. }
