131. export function createContentSecurityPolicy(): string {
132.   return [
133.     "default-src 'self'",
134.     "script-src 'self'",
135.     "style-src 'self' 'unsafe-inline'",
136.     "img-src 'self' data: blob:",
137.     "font-src 'self'",
138.     "connect-src 'self'",
139.     "media-src 'none'",
140.     "object-src 'none'",
141.     "frame-src 'none'",
142.     "worker-src 'self' blob:",
143.     "base-uri 'none'",
144.     "form-action 'none'",
145.   ].join("; ");
146. }
