12. const DESKTOP_CHANNELS = Object.freeze({
13.   getState: "desktop:get-state",
14.   toggleFullscreen: "desktop:toggle-fullscreen",
15.   fullscreenChanged: "desktop:fullscreen-changed",
16. });
