18. function isDesktopPlatform(value: unknown): value is DesktopPlatform {
19.   return value === "linux"
20.     || value === "macos"
21.     || value === "windows"
22.     || value === "other";
23. }
24. 
25. function readDesktopState(value: unknown): DesktopState {
26.   if (
27.     typeof value !== "object"
28.     || value === null
29.     || !("appVersion" in value)
30.     || typeof value.appVersion !== "string"
31.     || !("isFullscreen" in value)
32.     || typeof value.isFullscreen !== "boolean"
33.     || !("platform" in value)
34.     || !isDesktopPlatform(value.platform)
35.   ) {
36.     throw new Error("Desktop main process returned an invalid window state");
37.   }
38.   return {
39.     appVersion: value.appVersion,
40.     isFullscreen: value.isFullscreen,
41.     platform: value.platform,
42.   };
43. }
44. 
45. const desktopApi: DesktopApi = Object.freeze({
46.   async getState(): Promise<DesktopState> {
47.     const value: unknown = await ipcRenderer.invoke(DESKTOP_CHANNELS.getState);
48.     return readDesktopState(value);
49.   },
50.   async toggleFullscreen(): Promise<boolean> {
51.     const value: unknown = await ipcRenderer.invoke(
52.       DESKTOP_CHANNELS.toggleFullscreen,
53.     );
54.     if (typeof value !== "boolean") {
55.       throw new Error("Desktop main process returned an invalid fullscreen state");
56.     }
57.     return value;
58.   },
59.   onFullscreenChanged(listener: (isFullscreen: boolean) => void): () => void {
60.     const handleChange = (
61.       _event: IpcRendererEvent,
62.       value: unknown,
63.     ): void => {
64.       if (typeof value === "boolean") listener(value);
65.     };
66.     ipcRenderer.on(DESKTOP_CHANNELS.fullscreenChanged, handleChange);
67.     return () => {
68.       ipcRenderer.removeListener(
69.         DESKTOP_CHANNELS.fullscreenChanged,
70.         handleChange,
71.       );
72.     };
73.   },
74. });
75. 
76. contextBridge.exposeInMainWorld("desktop", desktopApi);
