73. /** Append a message to the HTML debug log panel. */
74. export function debugPanelLog(msg: string, isDebugMsg = false, cssClass?: string): void {
75.   const el = getDebugLogEl();
76.   if (!el) return;
77.   // Remove previous spacer if present
78.   const oldSpacer = el.querySelector(".log-spacer");
79.   if (oldSpacer) oldSpacer.remove();
80.   // Add the log line
81.   const line = document.createElement("div");
82.   line.textContent = msg;
83.   if (cssClass) line.className = cssClass;
84.   else if (isDebugMsg) line.className = "debug-msg";
85.   el.appendChild(line);
86.   // Trim oldest lines if over limit
87.   const lines = el.querySelectorAll("div:not(.log-spacer)");
88.   if (lines.length > MAX_DEBUG_LOG_LINES) {
89.     const toRemove = lines.length - MAX_DEBUG_LOG_LINES;
90.     for (let i = 0; i < toRemove; i++) lines[i].remove();
91.   }
92.   // Add trailing spacer for readability
93.   const spacer = document.createElement("div");
94.   spacer.className = "log-spacer";
