38. async function waitForServer(url, child) {
39.   const deadline = Date.now() + 30_000;
40.   while (Date.now() < deadline) {
41.     if (child.exitCode !== null) {
42.       throw new Error(`Vite exited before Electron started (${child.exitCode})`);
43.     }
44.     try {
45.       const response = await fetch(url);
46.       if (response.ok) return;
47.     } catch {
48.       // Vite is still starting.
49.     }
50.     await new Promise((resolveDelay) => setTimeout(resolveDelay, 150));
51.   }
52.   throw new Error(`Timed out waiting for Vite at ${url}`);
53. }
54. 
55. function stopChild(child) {
56.   if (child && child.exitCode === null && !child.killed) {
57.     child.kill("SIGTERM");
58.   }
59. }
60. 
61. const port = await findAvailablePort();
62. const rendererUrl = `http://127.0.0.1:${port}/`;
63. const vite = spawn(
64.   vitePath,
65.   ["--host", "127.0.0.1", "--port", String(port), "--strictPort"],
66.   {
67.     cwd: root,
68.     env: process.env,
69.     stdio: "inherit",
70.   },
71. );
72. 
73. let electron;
74. const shutdown = () => {
75.   stopChild(electron);
76.   stopChild(vite);
77. };
78. process.once("SIGINT", shutdown);
79. process.once("SIGTERM", shutdown);
80. 
81. try {
82.   await waitForServer(rendererUrl, vite);
83.   process.stdout.write(`[desktop] Starting Electron at ${rendererUrl}\n`);
84.   electron = spawn(electronPath, [root], {
85.     cwd: root,
86.     env: {
87.       ...process.env,
88.       ELECTRON_RENDERER_URL: rendererUrl,
89.     },
90.     stdio: "inherit",
91.   });
92.   const [exitCode] = await once(electron, "exit");
93.   process.exitCode = typeof exitCode === "number" ? exitCode : 1;
94. } catch (error) {
95.   process.stderr.write(
96.     `[desktop] Development startup failed: ${
97.       error instanceof Error ? error.stack ?? error.message : String(error)
98.     }\n`,
99.   );
100.   process.exitCode = 1;
101. } finally {
102.   shutdown();
103. }
