1. import { mkdir, writeFile } from "node:fs/promises";
2. import { resolve } from "node:path";
3. import { deflateSync } from "node:zlib";
4. 
5. const ICON_SIZES = Object.freeze([16, 32, 48, 64, 128, 256, 512, 1024]);
6. const PNG_SIGNATURE = Buffer.from([
7.   0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a,
8. ]);
9. const COLORS = Object.freeze({
10.   transparent: [0, 0, 0, 0],
11.   background: [13, 16, 36, 255],
12.   backgroundLight: [26, 31, 62, 255],
13.   gold: [255, 215, 0, 255],
14.   goldLight: [255, 239, 139, 255],
15.   ink: [5, 7, 18, 255],
16. });
17. const GLYPHS = Object.freeze({
18.   "2": ["111", "001", "111", "100", "111"],
19.   D: ["110", "101", "101", "101", "110"],
20. });
21. 
22. function crc32(buffer) {
23.   let crc = 0xffffffff;
24.   for (const byte of buffer) {
25.     crc ^= byte;
26.     for (let bit = 0; bit < 8; bit += 1) {
27.       crc = (crc >>> 1) ^ (0xedb88320 & -(crc & 1));
28.     }
29.   }
30.   return (crc ^ 0xffffffff) >>> 0;
31. }
32. 
33. function createPngChunk(type, data) {
34.   const typeBuffer = Buffer.from(type, "ascii");
35.   const length = Buffer.alloc(4);
36.   length.writeUInt32BE(data.length);
37.   const checksum = Buffer.alloc(4);
38.   checksum.writeUInt32BE(crc32(Buffer.concat([typeBuffer, data])));
39.   return Buffer.concat([length, typeBuffer, data, checksum]);
40. }
41. 
42. function encodePng(size, pixels) {
43.   const header = Buffer.alloc(13);
44.   header.writeUInt32BE(size, 0);
45.   header.writeUInt32BE(size, 4);
46.   header[8] = 8;
47.   header[9] = 6;
48.   const rowLength = size * 4;
49.   const filtered = Buffer.alloc((rowLength + 1) * size);
50.   for (let y = 0; y < size; y += 1) {
51.     const targetOffset = y * (rowLength + 1);
52.     filtered[targetOffset] = 0;
53.     pixels.copy(
54.       filtered,
55.       targetOffset + 1,
56.       y * rowLength,
57.       (y + 1) * rowLength,
58.     );
59.   }
60.   return Buffer.concat([
61.     PNG_SIGNATURE,
62.     createPngChunk("IHDR", header),
63.     createPngChunk("IDAT", deflateSync(filtered, { level: 9 })),
64.     createPngChunk("IEND", Buffer.alloc(0)),
65.   ]);
66. }
67. 
68. function setPixel(pixels, x, y, color) {
69.   if (x < 0 || x >= 32 || y < 0 || y >= 32) return;
70.   const offset = (y * 32 + x) * 4;
71.   pixels[offset] = color[0];
72.   pixels[offset + 1] = color[1];
73.   pixels[offset + 2] = color[2];
74.   pixels[offset + 3] = color[3];
75. }
76. 
77. function fillPolygon(pixels, points, color) {
78.   for (let y = 0; y < 32; y += 1) {
79.     for (let x = 0; x < 32; x += 1) {
80.       let inside = false;
81.       for (
82.         let current = 0, previous = points.length - 1;
83.         current < points.length;
84.         previous = current, current += 1
85.       ) {
86.         const [currentX, currentY] = points[current];
87.         const [previousX, previousY] = points[previous];
88.         const crosses = (currentY > y) !== (previousY > y)
89.           && x < (
90.             (previousX - currentX) * (y - currentY)
91.             / (previousY - currentY)
92.             + currentX
93.           );
94.         if (crosses) inside = !inside;
95.       }
96.       if (inside) setPixel(pixels, x, y, color);
97.     }
98.   }
99. }
100. 
101. function drawLine(pixels, startX, startY, endX, endY, color) {
102.   const deltaX = Math.abs(endX - startX);
103.   const deltaY = -Math.abs(endY - startY);
104.   const stepX = startX < endX ? 1 : -1;
105.   const stepY = startY < endY ? 1 : -1;
106.   let error = deltaX + deltaY;
107.   let x = startX;
108.   let y = startY;
109.   while (true) {
110.     setPixel(pixels, x, y, color);
111.     if (x === endX && y === endY) return;
112.     const doubled = 2 * error;
113.     if (doubled >= deltaY) {
114.       error += deltaY;
115.       x += stepX;
116.     }
117.     if (doubled <= deltaX) {
118.       error += deltaX;
119.       y += stepY;
120.     }
121.   }
122. }
123. 
124. function drawGlyph(pixels, glyph, startX, startY, scale, color) {
125.   for (let row = 0; row < glyph.length; row += 1) {
126.     for (let column = 0; column < glyph[row].length; column += 1) {
127.       if (glyph[row][column] !== "1") continue;
128.       for (let y = 0; y < scale; y += 1) {
129.         for (let x = 0; x < scale; x += 1) {
130.           setPixel(
131.             pixels,
132.             startX + column * scale + x,
133.             startY + row * scale + y,
134.             color,
135.           );
136.         }
137.       }
138.     }
139.   }
140. }
141. 
142. function createBasePixels() {
143.   const pixels = Buffer.alloc(32 * 32 * 4);
144.   for (let y = 1; y < 31; y += 1) {
145.     for (let x = 1; x < 31; x += 1) {
146.       const cornerDistance = Math.hypot(
147.         Math.max(0, 5 - Math.min(x, 31 - x)),
148.         Math.max(0, 5 - Math.min(y, 31 - y)),
149.       );
150.       if (cornerDistance <= 5) {
151.         setPixel(
152.           pixels,
153.           x,
154.           y,
155.           x <= 2 || x >= 29 || y <= 2 || y >= 29
156.             ? COLORS.gold
157.             : COLORS.background,
158.         );
159.       }
160.     }
161.   }
162. 
163.   const die = [
164.     [16, 4],
165.     [27, 10],
166.     [27, 21],
167.     [16, 28],
168.     [5, 21],
169.     [5, 10],
170.   ];
171.   fillPolygon(pixels, die, COLORS.backgroundLight);
172.   for (let index = 0; index < die.length; index += 1) {
173.     const [startX, startY] = die[index];
174.     const [endX, endY] = die[(index + 1) % die.length];
175.     drawLine(pixels, startX, startY, endX, endY, COLORS.goldLight);
176.   }
177.   drawLine(pixels, 16, 4, 16, 28, COLORS.gold);
178.   drawLine(pixels, 5, 10, 27, 21, COLORS.gold);
179.   drawLine(pixels, 27, 10, 5, 21, COLORS.gold);
180.   drawGlyph(pixels, GLYPHS["2"], 9, 11, 2, COLORS.goldLight);
181.   drawGlyph(pixels, GLYPHS.D, 18, 11, 2, COLORS.goldLight);
182.   return pixels;
183. }
184. 
185. function scalePixels(basePixels, size) {
186.   const pixels = Buffer.alloc(size * size * 4);
187.   for (let y = 0; y < size; y += 1) {
188.     for (let x = 0; x < size; x += 1) {
189.       const sourceX = Math.min(31, Math.floor((x / size) * 32));
190.       const sourceY = Math.min(31, Math.floor((y / size) * 32));
191.       const sourceOffset = (sourceY * 32 + sourceX) * 4;
192.       const targetOffset = (y * size + x) * 4;
193.       basePixels.copy(pixels, targetOffset, sourceOffset, sourceOffset + 4);
194.     }
195.   }
196.   return pixels;
197. }
198. 
199. function createIco(images) {
200.   const selectedSizes = [16, 32, 48, 64, 128, 256];
201.   const header = Buffer.alloc(6);
202.   header.writeUInt16LE(0, 0);
203.   header.writeUInt16LE(1, 2);
204.   header.writeUInt16LE(selectedSizes.length, 4);
205.   const directory = Buffer.alloc(selectedSizes.length * 16);
206.   let offset = header.length + directory.length;
207.   const payloads = [];
208.   selectedSizes.forEach((size, index) => {
209.     const image = images.get(size);
210.     const entryOffset = index * 16;
211.     directory[entryOffset] = size === 256 ? 0 : size;
212.     directory[entryOffset + 1] = size === 256 ? 0 : size;
213.     directory[entryOffset + 2] = 0;
214.     directory[entryOffset + 3] = 0;
215.     directory.writeUInt16LE(1, entryOffset + 4);
216.     directory.writeUInt16LE(32, entryOffset + 6);
217.     directory.writeUInt32LE(image.length, entryOffset + 8);
218.     directory.writeUInt32LE(offset, entryOffset + 12);
219.     offset += image.length;
220.     payloads.push(image);
221.   });
222.   return Buffer.concat([header, directory, ...payloads]);
223. }
224. 
225. function createIcns(images) {
226.   const chunks = [
227.     ["icp4", 16],
228.     ["icp5", 32],
229.     ["icp6", 64],
230.     ["ic07", 128],
231.     ["ic08", 256],
232.     ["ic09", 512],
233.     ["ic10", 1024],
234.     ["ic11", 32],
235.     ["ic12", 64],
236.     ["ic13", 256],
237.     ["ic14", 512],
238.   ].map(([type, size]) => {
239.     const image = images.get(size);
240.     const header = Buffer.alloc(8);
241.     header.write(type, 0, "ascii");
242.     header.writeUInt32BE(image.length + 8, 4);
243.     return Buffer.concat([header, image]);
244.   });
245.   const totalLength = chunks.reduce(
246.     (length, chunk) => length + chunk.length,
247.     8,
248.   );
249.   const header = Buffer.alloc(8);
250.   header.write("icns", 0, "ascii");
251.   header.writeUInt32BE(totalLength, 4);
252.   return Buffer.concat([header, ...chunks]);
253. }
254. 
255. const buildDirectory = resolve(process.cwd(), "build");
256. const linuxDirectory = resolve(buildDirectory, "icons");
257. await mkdir(linuxDirectory, { recursive: true });
258. 
259. const basePixels = createBasePixels();
260. const images = new Map();
261. for (const size of ICON_SIZES) {
262.   const png = encodePng(size, scalePixels(basePixels, size));
263.   images.set(size, png);
264.   await writeFile(resolve(linuxDirectory, `${size}x${size}.png`), png);
265. }
266. await writeFile(resolve(buildDirectory, "icon.png"), images.get(1024));
267. await writeFile(resolve(buildDirectory, "icon.ico"), createIco(images));
268. await writeFile(resolve(buildDirectory, "icon.icns"), createIcns(images));
269. process.stdout.write(
270.   `[desktop] Generated ${ICON_SIZES.length} procedural icon sizes in build/\n`,
271. );
